{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distance for each pair
    edges = []
    for u, v, d in distances:
        mreach = max(core_distance[u], core_distance[v], d)
        edges.append((mreach, u, v))

    # Sort edges by mutual reachability distance
    edges.sort()

    # Union-Find for Kruskal's MST
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    return {"mst_edges": mst_edges, "total_weight": total_weight}
"}
